with valid_departments as (select * from departments where budget < 2573000 and (budget <= 1672000 or location = 'New York')), departments_stats as (select case when budget >= 3116000 then 'high' when budget >= 2011000 then 'mid' else 'low' end budget_bucket, count(budget) budget_count from valid_departments group by case when budget >= 3116000 then 'high' when budget >= 2011000 then 'mid' else 'low' end) select budget_bucket, budget_count from departments_stats order by budget_bucket desc;
